import pytest
from parsers import parse_kv_pairs


def test_empty_input_returns_empty_dict():
    """Empty string should yield empty dict."""
    assert parse_kv_pairs("") == {}


def test_only_whitespace_returns_empty_dict():
    """Whitespace-only input should yield empty dict."""
    assert parse_kv_pairs("   \t\n") == {}


def test_single_entry_with_whitespace_strips():
    """Whitespace around key and value should be stripped."""
    assert parse_kv_pairs("  a=  1  ") == {"a": "1"}


def test_single_entry_no_equals_raises_value_error():
    """Entry without '=' should raise ValueError."""
    with pytest.raises(ValueError, match=r"bad entry: 'a'"):
        parse_kv_pairs("a")

