import pytest

from containers import chunk


def test_chunk_empty():
    assert chunk([], 2) == []


def test_chunk_size_one():
    assert chunk([1, 2, 3, 4], 1) == [[1], [2], [3], [4]]


def test_chunk_size_equals_length():
    assert chunk([1, 2, 3], 3) == [[1, 2, 3]]


def test_chunk_size_greater_than_length():
    assert chunk([1, 2], 5) == [[1, 2]]


def test_chunk_negative_size_raises_value_error():
    with pytest.raises(ValueError, match="size must be >= 1"):
        chunk([1, 2], -1)


